// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // Precompute whether the internal call sequence will revert the transaction
        // by checking if caddress is an EOA (no code).  Low-level call to an EOA always returns
        // success and does not propagate reverts.  A contract could have a fallback that reverts
        // only when the selector doesn't match, but `caddress.call` will revert only if the callee
        // reverts with no error handling; since `caddress.call` is used without `require` on the
        // success value, the transfer transaction will NOT revert even if the subcall fails.
        // Thus transfer never reverts (aside from the _tos.length check) for any caddress.
        // The assertion should hold for all inputs where transfer does not revert.
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool returned) {
            ok = returned;
        } catch {
            // transfer reverted; input is not admissible for the property.
            vm.assume(false);
        }
        // The reference C always returns true when it does not revert.
        assertTrue(ok);
    }
}
